import { readFile, writeFile } from "node:fs/promises";
import { isBuiltin } from "node:module";
import { join } from "node:path";
import { build } from "tsdown";

/** Build only locked Desktop-owned entries; generated bytes join the capability tree hash. */
export async function compileOwnedExtension({ sourceRoot, entryPath, destination, bundleTypebox = false }) {
  const bundles = await build({
    config: false,
    tsconfig: false,
    entry: { index: join(sourceRoot, entryPath) },
    outDir: destination,
    outExtensions: () => ({ js: ".js" }),
    format: "esm",
    platform: "node",
    target: "node24",
    dts: false,
    sourcemap: false,
    clean: false,
    exports: false,
    logLevel: "error",
    deps: { alwaysBundle: bundleTypebox ? [/^typebox(?:\/|$)/u] : [] }
  });
  const chunks = bundles.flatMap((bundle) => bundle.chunks);
  if (chunks.length !== 1 || chunks[0].fileName !== "index.js"
    || chunks[0].dynamicImports.length !== 0 || !chunks[0].imports.every(isBuiltin)) {
    throw new Error("Compiled Desktop Extension must be one ESM entry with only Node built-in imports.");
  }
  if (bundleTypebox) {
    const declared = JSON.parse(await readFile(join(sourceRoot, "package.json"), "utf8"));
    const dependencyRoot = join(sourceRoot, "node_modules/typebox");
    const installed = JSON.parse(await readFile(join(dependencyRoot, "package.json"), "utf8"));
    if (installed.version !== declared.dependencies?.typebox || installed.license !== "MIT") {
      throw new Error("Compiled Extension TypeBox dependency does not match its locked source manifest.");
    }
    await writeFile(join(destination, "typebox.LICENSE"), await readFile(join(dependencyRoot, "license")));
  }
}
